Riverpod & Bloc Patterns:
// Riverpod: Todo app
import 'package:flutter_riverpod/flutter_riverpod.dart';

// Data layer
final todoRepositoryProvider = Provider<TodoRepository>((ref) => TodoRepository());

// State with StateNotifier
class TodoListNotifier extends StateNotifier<List<Todo>> {
  final TodoRepository _repo;

  TodoListNotifier(this._repo) : super([]);

  Future<void> loadTodos() async {
    state = await _repo.fetchAll();
  }

  void addTodo(String title) {
    state = [...state, Todo(id: uuid(), title: title)];
  }

  void toggleComplete(String id) {
    state = state.map((t) => t.id == id ? t.copyWith(completed: !t.completed) : t).toList();
  }

  void removeTodo(String id) {
    state = state.where((t) => t.id != id).toList();
  }
}

final todoListProvider = StateNotifierProvider<TodoListNotifier, List<Todo>>((ref) {
  return TodoListNotifier(ref.watch(todoRepositoryProvider));
});

// Derived state (computed)
final pendingTodosProvider = Provider<List<Todo>>((ref) {
  return ref.watch(todoListProvider).where((t) => !t.completed).toList();
});

// UI
class TodoListWidget extends ConsumerWidget {
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final todos = ref.watch(todoListProvider);
    final pending = ref.watch(pendingTodosProvider).length;

    return Scaffold(
      appBar: AppBar(title: Text('Todos ($pending pending)')),
      body: ListView.builder(
        itemCount: todos.length,
        itemBuilder: (context, i) => CheckboxListTile(
          value: todos[i].completed,
          title: Text(todos[i].title),
          onChanged: (_) => ref.read(todoListProvider.notifier).toggleComplete(todos[i].id),
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => ref.read(todoListProvider.notifier).addTodo('New task'),
        child: Icon(Icons.add),
      ),
    );
  }
}
